      "source": "aztec/final_permit.pdf",
      "locator": "Page: 10, Section: part_i",
      "exact_span": "**Test failure may not be construed or reported as invalid due to a coefficient of variation value of greater than 40%, or a PMSD value greater than the higher value on the range provided.",
